#include <stddef.h>

size_t count_even(const int values[], size_t count)
{
    size_t total = 0U;
    for (size_t i = 0; i < count; ++i) {
        if (values[i] % 2 == 0) {
            ++total;
        }
    }
    return total;
}

int main(void)
{
    const int readings[] = {12, 7, 4, 9, 6};
    return count_even(readings, sizeof readings / sizeof readings[0]) == 3U ? 0 : 1;
}

